//! Deterministic integer-only randomness: xoshiro256** seeded via splitmix64.
//! Re-implemented from the validated prototype; outputs are pinned by core/tests/fixtures/rng_vectors.txt
//! (generated by an independent Python port, tools/ref/platform_ref.py).

const GOLD: u64 = 0x9e37_79b9_7f4a_7c15;

fn mix(mut x: u64) -> u64 {
    x = (x ^ (x >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);
    x = (x ^ (x >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);
    x ^ (x >> 31)
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Rng {
    s: [u64; 4],
}

impl Rng {
    pub fn new(seed: u64) -> Self {
        let mut z = seed;
        let mut s = [0u64; 4];
        for slot in s.iter_mut() {
            z = z.wrapping_add(GOLD);
            *slot = mix(z);
        }
        Rng { s }
    }

    pub fn from_state(s: [u64; 4]) -> Self {
        Rng { s }
    }

    pub fn state(&self) -> [u64; 4] {
        self.s
    }

    #[inline]
    pub fn next_u64(&mut self) -> u64 {
        let result = self.s[1].wrapping_mul(5).rotate_left(7).wrapping_mul(9);
        let t = self.s[1] << 17;
        self.s[2] ^= self.s[0];
        self.s[3] ^= self.s[1];
        self.s[1] ^= self.s[2];
        self.s[0] ^= self.s[3];
        self.s[2] ^= t;
        self.s[3] = self.s[3].rotate_left(45);
        result
    }

    /// Unbiased integer in [0, n). Panics if n == 0.
    pub fn below(&mut self, n: u64) -> u64 {
        assert!(n > 0, "Rng::below(0)");
        let threshold = n.wrapping_neg() % n; // 2^64 mod n
        loop {
            let r = self.next_u64();
            if r >= threshold {
                return r % n;
            }
        }
    }
}

/// Named, independent random streams so that adding a feature never reshuffles another feature's randomness.
pub const STREAM_COLLAPSE: usize = 0;
pub const STREAM_EVENTS: usize = 1;
pub const STREAM_GENESIS: usize = 2;
pub const NUM_STREAMS: usize = 3;

pub fn stream_seed(seed: u64, id: usize) -> u64 {
    mix(seed.wrapping_add((id as u64 + 1).wrapping_mul(GOLD)))
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RngStreams {
    streams: Vec<Rng>,
}

impl RngStreams {
    pub fn new(seed: u64) -> Self {
        let streams = (0..NUM_STREAMS).map(|i| Rng::new(stream_seed(seed, i))).collect();
        RngStreams { streams }
    }

    pub fn from_states(states: &[[u64; 4]]) -> Self {
        RngStreams { streams: states.iter().map(|s| Rng::from_state(*s)).collect() }
    }

    pub fn stream(&mut self, id: usize) -> &mut Rng {
        &mut self.streams[id]
    }

    pub fn states(&self) -> Vec<[u64; 4]> {
        self.streams.iter().map(|r| r.state()).collect()
    }
}
